def by_length(arr):
    num_to_name = {1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five", 
                   6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"}
    within_range = sorted([x for x in arr if 1 <= x <= 9], reverse=True)
    others = sorted([x for x in arr if x < 1 or x > 9], reverse=True)
    if within_range:
        return [num_to_name[x] for x in within_range]
    elif others:
        return [num_to_name[x] for x in others]
    return []
